#!/usr/bin/env bash
# Print the three most frequent IP addresses in access.log,
# one per line, most frequent first; ties broken by first appearance.
set -eu

awk '{
    if (!seen[$1]++) first[$1] = ++order
}
END {
    n = 0
    for (ip in seen) {
        n++
        ip_list[n] = ip
        count[n] = seen[ip]
        pos[n] = first[ip]
    }
    # sort: descending count, then ascending first-appearance order
    for (i = 1; i <= n; i++) {
        for (j = i + 1; j <= n; j++) {
            if (count[j] > count[i] || (count[j] == count[i] && pos[j] < pos[i])) {
                t = ip_list[i]; ip_list[i] = ip_list[j]; ip_list[j] = t
                t = count[i]; count[i] = count[j]; count[j] = t
                t = pos[i]; pos[i] = pos[j]; pos[j] = t
            }
        }
    }
    top = (n < 3) ? n : 3
    for (i = 1; i <= top; i++) print ip_list[i]
}' access.log
